sections.syntax:
UPDATE nom_table
SET colonne1 = valeur1, colonne2 = valeur2, ...
WHERE condition;

examples.code:
UPDATE Students
SET email = 'alice.new@example.com'
WHERE id = 1;

UPDATE Employees
SET salary = salary * 1.10
WHERE department = 'Sales';

UPDATE Products
SET price = price * 0.90
WHERE product_id IN (
  SELECT product_id FROM Promotions WHERE active = 1
);

DELETE FROM Orders
WHERE status = 'cancelled'
  AND order_date < '2024-01-01';

DELETE FROM Orders
WHERE customer_id IN (
  SELECT customer_id FROM Customers WHERE country = 'France'
);

-- ATTENTION : Ceci supprime TOUTES les lignes !
DELETE FROM Students;

-- Utilisez toujours WHERE :
DELETE FROM Students
WHERE id = 5;

-- DELETE (lent, ligne par ligne, supporte WHERE) :
DELETE FROM Students;

-- TRUNCATE (rapide, tout d'un coup, pas de WHERE) :
TRUNCATE TABLE Students;
